CREATE TYPE "UserRole" AS ENUM ('REPORTER', 'AGENT');
CREATE TYPE "Priority" AS ENUM ('LOW', 'MEDIUM', 'HIGH', 'URGENT');
CREATE TYPE "TicketStatus" AS ENUM ('OPEN', 'IN_PROGRESS', 'WAITING_ON_CUSTOMER', 'RESOLVED', 'CLOSED');
CREATE TYPE "EventType" AS ENUM ('CREATED', 'ASSIGNED', 'STATUS_CHANGED', 'COMMENTED', 'PAUSED', 'RESUMED', 'RESOLVED', 'REOPENED');
CREATE TABLE "User" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "role" "UserRole" NOT NULL DEFAULT 'REPORTER', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Ticket" ("id" TEXT NOT NULL, "reference" SERIAL NOT NULL, "title" TEXT NOT NULL CHECK (length(trim("title")) > 0), "description" TEXT NOT NULL CHECK (length(trim("description")) > 0), "priority" "Priority" NOT NULL, "status" "TicketStatus" NOT NULL DEFAULT 'OPEN', "reporterId" TEXT NOT NULL, "assigneeId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "firstResponseAt" TIMESTAMP(3), "resolvedAt" TIMESTAMP(3), "firstResponseDueAt" TIMESTAMP(3) NOT NULL, "firstResponseAtRiskAt" TIMESTAMP(3) NOT NULL, "resolutionDueAt" TIMESTAMP(3) NOT NULL, "resolutionAtRiskAt" TIMESTAMP(3) NOT NULL, "firstResponseSlaMet" BOOLEAN, "resolutionSlaMet" BOOLEAN, "slaPausedAt" TIMESTAMP(3), "slaPausedMinutes" INTEGER NOT NULL DEFAULT 0 CHECK ("slaPausedMinutes" >= 0), CONSTRAINT "Ticket_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Comment" ("id" TEXT NOT NULL, "content" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "ticketId" TEXT NOT NULL, "authorId" TEXT NOT NULL, CONSTRAINT "Comment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Holiday" ("id" TEXT NOT NULL, "date" DATE NOT NULL, "name" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Holiday_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TicketEvent" ("id" TEXT NOT NULL, "type" "EventType" NOT NULL, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "ticketId" TEXT NOT NULL, "actorId" TEXT NOT NULL, CONSTRAINT "TicketEvent_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "Ticket_reference_key" ON "Ticket"("reference"); CREATE UNIQUE INDEX "Holiday_date_key" ON "Holiday"("date");
CREATE INDEX "Ticket_status_idx" ON "Ticket"("status"); CREATE INDEX "Ticket_priority_idx" ON "Ticket"("priority"); CREATE INDEX "Ticket_assigneeId_idx" ON "Ticket"("assigneeId"); CREATE INDEX "Ticket_firstResponseDueAt_idx" ON "Ticket"("firstResponseDueAt"); CREATE INDEX "Ticket_resolutionDueAt_idx" ON "Ticket"("resolutionDueAt"); CREATE INDEX "Ticket_createdAt_id_idx" ON "Ticket"("createdAt" DESC, "id" DESC);
ALTER TABLE "Ticket" ADD CONSTRAINT "Ticket_reporterId_fkey" FOREIGN KEY ("reporterId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Ticket" ADD CONSTRAINT "Ticket_assigneeId_fkey" FOREIGN KEY ("assigneeId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "Comment" ADD CONSTRAINT "Comment_ticketId_fkey" FOREIGN KEY ("ticketId") REFERENCES "Ticket"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Comment" ADD CONSTRAINT "Comment_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "TicketEvent" ADD CONSTRAINT "TicketEvent_ticketId_fkey" FOREIGN KEY ("ticketId") REFERENCES "Ticket"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "TicketEvent" ADD CONSTRAINT "TicketEvent_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
